(() => {
  const windows=[['3个月',63],['6个月',126],['12个月',252]]; let all=[], sequence=0, controller;
  const n=v=>Number.isFinite(v)?v.toFixed(2):'—', labels={live:'最新来源',cached:'数据库缓存',stale:'数据已过期',missing:'来源缺失'};
  const moving=(rows,size)=>rows.map((r,i)=>i+1>=size?rows.slice(i-size+1,i+1).reduce((s,x)=>s+x.c,0)/size:null);
  function draw(rows,window){const svg=$('history-chart'),bars=$('history-volume');if(!svg||!rows.length){if(svg)svg.innerHTML='';if(bars)bars.innerHTML='';return}const start=Math.max(0,rows.length-window),shown=rows.slice(start),m50=moving(rows,50).slice(start),m200=moving(rows,200).slice(start),vals=shown.flatMap((r,i)=>[r.c,m50[i],m200[i]]).filter(Number.isFinite),max=Math.max(...vals),min=Math.min(...vals),w=800,h=280,p=38,x=i=>p+i*(w-2*p)/Math.max(1,shown.length-1),y=v=>h-p-(v-min)/(max-min||1)*(h-2*p),path=(a,c)=>{let d='';a.forEach((v,i)=>{if(Number.isFinite(v))d+=(d?'L':'M')+x(i).toFixed(1)+','+y(v).toFixed(1)});return `<path d="${d}" fill="none" stroke="${c}" stroke-width="2"/>`};svg.innerHTML=`<title>收盘价与移动平均线</title><desc>均线先按完整返回序列计算，历史不足处留空。</desc><line x1="${p}" y1="${p}" x2="${p}" y2="${h-p}" stroke="#b8c8cf"/><line x1="${p}" y1="${h-p}" x2="${w-p}" y2="${h-p}" stroke="#b8c8cf"/><text x="4" y="${p+4}">${n(max)}</text><text x="4" y="${h-p}">${n(min)}</text><text x="${p}" y="${h-6}">${esc(shown[0].date)}</text><text x="${w-p-72}" y="${h-6}">${esc(shown.at(-1).date)}</text>${path(shown.map(r=>r.c),'#24576c')}${path(m50,'#b36b32')}${path(m200,'#6c5b95')}<g class="history-legend"><text fill="#24576c" x="50" y="20">收盘</text><text fill="#b36b32" x="110" y="20">MA50</text><text fill="#6c5b95" x="175" y="20">MA200</text></g>`;if(bars){const vmax=Math.max(...shown.map(r=>r.v),1);bars.innerHTML=shown.map((r,i)=>{if(!Number.isFinite(r.v))return "";const ht=Math.max(1,r.v/vmax*70);return `<rect x="${x(i)-1}" y="${82-ht}" width="2" height="${ht}" aria-label="${esc(r.date)} 成交量 ${esc(r.v)}"/>`}).join('')}}
  async function loadHistory(){const box=$('history-status'),my=++sequence;controller?.abort();controller=new AbortController();box.textContent='正在读取日线…';all=[];draw([],0);try{const symbol=$('symbol').value,r=await fetch('/api/history?symbol='+encodeURIComponent(symbol),{signal:controller.signal});if(!r.ok)throw Error();const d=await r.json();if(my!==sequence)return;all=(d.bars||[]).map(x=>({date:x.date,c:Number(x.c??x.close),v:(x.v??x.volume)==null?null:Number(x.v??x.volume)})).filter(x=>Number.isFinite(x.c)&&x.c>0);if(!all.length){box.textContent='暂无可用历史数据。';return}box.textContent=`${d.symbol} · ${all.length} 根 · ${d.status==='review'?'价格跳变待核实':d.status==='stale'?'数据已过期':labels[d.dataStatus||d.status]||'状态待确认'} · ${{ok:'已保存到数据库',error:'数据库读写失败',disabled:'尚未启用保存'}[d.storageStatus]||'保存状态未知'} · 来源：${d.source||'未知'} · 最新日期：${all.at(-1).date} · 抓取：${d.retrievedAt?new Date(d.retrievedAt).toLocaleString():'未知'} · 最新收盘 ${n(all.at(-1).c)}`;draw(all,Number($('history-window').value));}catch(e){if(e.name==='AbortError'||my!==sequence)return;all=[];draw([],0);box.textContent='历史数据暂不可用，请稍后重试。'}}
  function ensure(){if($('history-section'))return;const ref=$('fundamental-status')?.closest('details')||$('stock-detail');const section=document.createElement('section');section.id='history-section';section.className='evidence-panel';section.innerHTML='<div class="section-head"><h2>日线历史</h2><span>收盘与均线</span></div><div class="history-toolbar"><label>窗口 <select id="history-window"><option value="63">3个月</option><option value="126" selected>6个月</option><option value="252">12个月</option></select></label><button id="history-refresh">刷新历史</button></div><p id="history-status" role="status">等待数据</p><div class="history-chart-wrap"><svg id="history-chart" viewBox="0 0 800 280" role="img"></svg><svg id="history-volume" viewBox="0 0 800 90" aria-label="成交量"></svg></div><p class="muted">原始收盘价（美元），下图为成交量。历史长度取决于来源；不足200日时不显示200日均线。仅打开页面或刷新时更新。</p>';ref?.before(section);$('history-window').onchange=()=>draw(all,Number($('history-window').value));$('history-refresh').onclick=loadHistory;}
  ensure();$('symbol')?.addEventListener('change',loadHistory);$('refresh')?.addEventListener('click',loadHistory);$('refresh-all')?.addEventListener('click',loadHistory);loadHistory();
})();
